def count_integers(lst):
    # Create an empty dictionary to store the count of each integer
    count_dict = {}

    # Loop through the list and add each integer to the dictionary with a count of 1
    for num in lst:
        if num in count_dict:
            count_dict[num] += 1
        else:
            count_dict[num] = 1

    # Return the dictionary containing the count of each integer
    return count_dict

# Example usage
